mapper.select:
SELECT , count(s.id) AS skill_count FROM tag t LEFT JOIN skill_tag st ON st.tag_id = t.id LEFT JOIN skill s ON s.id = st.skill_id AND s.status = 'PUBLISHED'
AND t.kind = #{kind}
GROUP BY t.id ORDER BY t.kind, t.sort_order, t.name

SELECT , count(s.id) AS skill_count FROM tag t LEFT JOIN skill_tag st ON st.tag_id = t.id LEFT JOIN skill s ON s.id = st.skill_id AND s.status = 'PUBLISHED' WHERE lower(t.name) LIKE '%' || lower(#{keyword}) || '%'
AND t.kind = #{kind}
GROUP BY t.id ORDER BY count(s.id) DESC, t.name LIMIT #{limit}

SELECT id, name, kind, description, sort_order, created_by_user_id, created_at, updated_at
FROM tag
WHERE name = #{name}

SELECT id, name, kind, description, sort_order, created_by_user_id, created_at, updated_at
FROM tag
WHERE id = #{tagId}

mapper.update:
UPDATE tag
SET name        = #{name},
    kind        = #{kind},
    description = #{description},
    sort_order  = #{sortOrder}
WHERE id = #{tagId}

mapper.select:
SELECT s.name
FROM skill_tag st
JOIN skill s ON s.id = st.skill_id
WHERE st.tag_id = #{tagId}
ORDER BY s.name
LIMIT #{limit}

SELECT s.name
FROM skill_tag st
JOIN skill s ON s.id = st.skill_id
WHERE st.tag_id = #{tagId}
  AND (
      SELECT count(*)
      FROM skill_tag inner_st
      JOIN tag inner_t ON inner_t.id = inner_st.tag_id
      WHERE inner_st.skill_id = st.skill_id
        AND inner_t.kind = 'CURATED'
  ) >= #{curatedLimit}
ORDER BY s.name
LIMIT #{limit}

mapper.insert:
INSERT INTO skill_tag (skill_id, tag_id)
SELECT st.skill_id, #{toTagId}
FROM skill_tag st
WHERE st.tag_id = #{fromTagId}
  AND NOT EXISTS (
      SELECT 1 FROM skill_tag existing
      WHERE existing.skill_id = st.skill_id AND existing.tag_id = #{toTagId}
  )
